AArch64 to PPC

"MOV %r,&c" -> "li %r,&c"
"STR %r,[%a]" -> "stw %r,0(%a)"
"LDR %r,[%a]" -> "lwz %r,0(%a)"
"STLR %r,[%a]" -> "stw %r,0(%a)"
"LDAR %r,[%a]" -> "lwz %r,0(%a)"
"LDAPR %r,[%a]" -> "lwz %r,0(%a)"
"DMB SY" -> "li r0,0"
"DMB LD" -> "li r0,0"
"DMB ST" -> "li r0,0"
# No fences at all, as everywhere else in this file. A negative control.
"LDXR %r,[%a]; STXR W%s,W%v,[%a]" -> "lwarx %r,r0,%a; li %s,1; stwcx. %v,r0,%a; bne xd; li %s,0; xd:"
"LDAXR %r,[%a]; STXR W%s,W%v,[%a]" -> "lwarx %r,r0,%a; li %s,1; stwcx. %v,r0,%a; bne xd; li %s,0; xd:"
"LDXR %r,[%a]; STLXR W%s,W%v,[%a]" -> "lwarx %r,r0,%a; li %s,1; stwcx. %v,r0,%a; bne xd; li %s,0; xd:"
"LDAXR %r,[%a]; STLXR W%s,W%v,[%a]" -> "lwarx %r,r0,%a; li %s,1; stwcx. %v,r0,%a; bne xd; li %s,0; xd:"
